class ResultType {
    int data;
public:
    ResultType() {}
    // Delete copy constructor to ensure RVO/Elision happens
    ResultType(const ResultType&) = delete;
    ResultType(ResultType&&) = default;
};

// Named Return Value Optimization (NRVO)
ResultType factory_nrvo() {
    ResultType local_result;
    return local_result; // Copy elided
}

// Guaranteed RVO (prvalue, C++17+)
ResultType factory_grvo() {
    return ResultType(); // Copy elided (guaranteed)
}

// Usage: ResultType obj = factory_nrvo();
